"use client";

/* Responsive, pre-encoded local images are generated by the build pipeline. */
/* eslint-disable @next/next/no-img-element */
import { useEffect, useRef, useState, type CSSProperties } from "react";
import { defaultVariant, variants, frames, lenses, type VariantId } from "@/content/variants";
import styles from "./Configurator.module.css";

type Preview = { id: VariantId; src: string; generation: number };
type Status = "ready" | "loading" | "error";

export function Configurator() {
  const [requested, setRequested] = useState<VariantId>(defaultVariant.id);
  const [displayed, setDisplayed] = useState<Preview>({ id: defaultVariant.id, src: "/images/obsidian-clear-960.webp", generation: 0 });
  const [status, setStatus] = useState<Status>("ready");
  const [initialFailed, setInitialFailed] = useState(false);
  const [previous, setPrevious] = useState<Preview | null>(null);
  const [shine, setShine] = useState<number | null>(null);
  const version = useRef(0);
  const pendingShine = useRef<number | null>(null);
  const stage = useRef<HTMLElement>(null);
  const image = useRef<HTMLImageElement>(null);
  const active = variants.find((variant) => variant.id === requested)!;
  const visible = variants.find((variant) => variant.id === displayed.id)!;

  useEffect(() => {
    const initial = image.current;
    // Image errors can precede hydration, so reconcile a failed SSR image after mount.
    if (initial?.complete && initial.naturalWidth === 0) {
      void initial.decode().catch(() => {
        if (version.current !== 0) return;
        setInitialFailed(true);
        setStatus("error");
      });
    }
    return () => { version.current += 1; };
  }, []);

  useEffect(() => {
    if (!previous) return;
    const timer = window.setTimeout(() => setPrevious(null), 240);
    return () => window.clearTimeout(timer);
  }, [previous]);

  async function select(id: VariantId, force = false) {
    const request = ++version.current;
    pendingShine.current = null;
    setShine(null);
    setRequested(id);
    if (id === displayed.id && !force && !initialFailed) {
      setStatus("ready");
      return;
    }
    setStatus("loading");
    const pixels = (stage.current?.clientWidth ?? 640) * Math.min(window.devicePixelRatio || 1, 2);
    const width = pixels <= 640 ? 640 : pixels <= 960 ? 960 : 1440;
    const src = `/images/${id}-${width}.webp`;
    const next = new Image();
    next.decoding = "async";
    next.src = src;
    try {
      await next.decode();
      if (request !== version.current) return;
      const oldSrc = image.current?.currentSrc || displayed.src;
      if (!initialFailed && !window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        setPrevious({ ...displayed, src: oldSrc });
      } else {
        setPrevious(null);
      }
      // A retry may decode the same URL; replace the previously broken DOM image too.
      if (id !== displayed.id && !initialFailed && !window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        pendingShine.current = request;
      }
      setDisplayed({ id, src, generation: request });
      setInitialFailed(false);
      setStatus("ready");
    } catch {
      if (request === version.current) setStatus("error");
    }
  }

  const message = status === "loading"
    ? `Loading ${active.label}. ${initialFailed ? "Preview unavailable." : `Still showing ${visible.label}.`}`
    : status === "error"
      ? `Could not load ${active.label}. ${initialFailed ? "Preview unavailable." : `Still showing ${visible.label}.`}`
      : `Showing ${visible.label}.`;

  return <section id="configure" className={styles.section} aria-labelledby="configure-title">
    <div className={styles.sectionLabel}><span>04 / Your perspective</span><span>OLVR ONE</span></div>
    <div className={styles.layout}>
      <div className={styles.intro}><p className={styles.eyebrow}>Considered in every shade.</p><h2 id="configure-title" tabIndex={-1}>Make it yours.</h2><p>Nine expressions.<br /> One familiar silhouette.</p></div>
      <figure ref={stage} className={styles.preview} data-displayed-variant={initialFailed ? undefined : displayed.id} aria-label="Product preview" aria-busy={status === "loading"}>
        <div className={styles.imageBox}>
          {initialFailed && <div className={styles.unavailable}>Preview unavailable.<br /><span>Your options are still here.</span></div>}
          <img key={`image-${displayed.generation}`} ref={image} src={displayed.src} srcSet={displayed.id === defaultVariant.id && displayed.src.endsWith("960.webp") ? "/images/obsidian-clear-640.webp 640w, /images/obsidian-clear-960.webp 960w, /images/obsidian-clear-1440.webp 1440w" : undefined} sizes="(max-width: 760px) calc(100vw - 48px), 60vw" width={1672} height={941} alt={visible.alt} loading="lazy" decoding="async" onLoad={() => { if (pendingShine.current === displayed.generation && !window.matchMedia("(prefers-reduced-motion: reduce)").matches) { pendingShine.current = null; setShine(displayed.generation); } }} onError={() => { pendingShine.current = null; setShine(null); setInitialFailed(true); setStatus("error"); }} className={initialFailed ? styles.hiddenImage : styles.product} />
          {previous && <img key={previous.src} src={previous.src} width={1672} height={941} className={styles.previous} alt="" aria-hidden="true" onAnimationEnd={() => setPrevious(null)} />}
          {shine === displayed.generation && status === "ready" && !initialFailed && <span key={`shine-${shine}`} className={styles.shine} aria-hidden="true" onAnimationEnd={() => setShine(null)} />}
          <span className={styles.corner} aria-hidden="true" />
        </div>
        <figcaption><span>{initialFailed ? "Preview unavailable" : visible.label}</span><span>Concept finish</span></figcaption>
      </figure>
      <div className={styles.controls}>
        <fieldset className={styles.options}>
          <legend>Frame finish</legend>
          {frames.map(frame => <label className={styles.option} key={frame.id} style={{ "--swatch": frame.swatch } as CSSProperties}>
            <input type="radio" name="frame" value={frame.id} checked={active.frame === frame.id} onChange={() => void select(`${frame.id}-${active.lens}`)} />
            <span className={styles.swatch} aria-hidden="true" /><span>{frame.label}</span><span className={styles.optionEnd} aria-hidden="true">{active.frame === frame.id ? "✓" : ""}</span>
          </label>)}
        </fieldset>
        <fieldset className={`${styles.options} ${styles.lenses}`} aria-describedby="variant-help">
          <legend>Lens appearance</legend>
          {lenses.map(lens => <label className={styles.option} key={lens.id}>
            <input type="radio" name="lens" value={lens.id} checked={active.lens === lens.id} onChange={() => void select(`${active.frame}-${lens.id}`)} />
            <span>{lens.label}</span><span className={styles.optionEnd} aria-hidden="true">{active.lens === lens.id ? "✓" : ""}</span>
          </label>)}
        </fieldset>
        <p id="variant-help" className={styles.help}>Adaptive is a fixed simulated appearance.</p>
        <div className={styles.feedback}>
          <p className={styles.description}>{active.description}</p>
          <p className={styles.status} role="status" aria-live="polite" aria-atomic="true"><span className={`${styles.statusDot} ${status === "loading" ? styles.loading : ""}`} aria-hidden="true" />{message}</p>
          <div className={styles.actions}>
            {status === "error" && <button className={styles.retry} onClick={() => void select(requested, true)}>Try again <span aria-hidden="true">↗</span></button>}
            <button className={styles.reset} onClick={() => void select(defaultVariant.id)}>Reset selection <span aria-hidden="true">↺</span></button>
          </div>
        </div>
        <noscript><p className={styles.help}>Enable JavaScript to explore nine combinations. Obsidian / Clear is shown above.</p></noscript>
      </div>
    </div>
  </section>;
}
